export function evaluate({inputs,time}){const u=inputs.launchSpeed,g=inputs.gravity,m=inputs.mass;const T=2*u/g;const t=Math.min(Math.max(time,0),T);const ta=u/g;const v=u-g*t,y=u*t-g*t*t/2;const ah=u*u/(2*g);const F=m*g;let st;if(time<=0)st='Ready to toss';else if(t>=T)st='Back at launch height';else if(Math.abs(t-ta)<0.005)st='At the top';else st=t<ta?'Rising':'Falling';
const o=[];o.push(...sdk.panel({id:'lane.motion',x:10,y:30,w:305,h:380,title:'The motion',state:st}));o.push(...sdk.panel({id:'lane.graph',x:325,y:30,w:305,h:380,title:'Velocity over time',state:''}));
o.push(sdk.axis('axis.h',{x:60,y:390,length:320,orientation:'y',min:0,max:2.2,ticks:[0,1,2],label:'Height',unit:'m'}));
const by=390-y/2.2*320;o.push(sdk.circle('ball.toss',130,by,26,{}));
o.push(...sdk.vector('vec.v',{x:130,y:by},{value:v,direction:'up'},{scale:14,label:'v',role:'input'}));
o.push(...sdk.vector('vec.a',{x:100,y:by},{value:-g,direction:'up'},{scale:7,label:'a',role:'warning'}));
o.push(...sdk.callout(170,by,['v '+sdk.format(v,2)+' m/s','a '+sdk.format(-g,1)+' m/s²','Fg '+sdk.format(F,1)+' N'],{id:'callout.toss'}));
const pts=[];for(let i=0;i<=12;i++){const tt=1.8*i/12;pts.push({x:tt,y:Math.max(-5.5,Math.min(5.5,u-g*tt))});}
o.push(sdk.plot('plot.vt',{x:385,y:60,w:240,h:290,axes:{x:{label:'t',unit:'s',min:0,max:1.8},y:{label:'v',unit:'m/s',min:-5.5,max:5.5}},series:[{label:'v = u - g t',kind:'line',points:pts}]}));
o.push(sdk.text('plot.vt.note',500,395,'slope a = -g = '+sdk.format(-g,1),{role:'warning'}));
return{frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:F},{id:'motionState',value:st}]},quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:ah,height:y,velocity:v,acceleration:-g,force:F}};}
